const body = msg.payload;
function invalid(error) {
    msg.statusCode = 400;
    msg.headers = {"Content-Type": "application/json"};
    msg.payload = {success: false, error};
    return [null, msg];
}
if (!body || typeof body !== "object" || Array.isArray(body)) return invalid("A JSON object is required.");
if (typeof body.tileSize !== "string" || !body.tileSize.trim()) return invalid("tileSize is required.");
if (typeof body.designCode !== "string" || !body.designCode.trim()) return invalid("designCode is required.");
if (body.designCode.trim().length > 100) return invalid("designCode must be at most 100 characters.");
if (body.description !== undefined && typeof body.description !== "string") return invalid("description must be a string.");
if (body.active !== undefined && typeof body.active !== "boolean") return invalid("active must be a boolean.");
const now = new Date();
const design = {
    tileSize: body.tileSize.trim(),
    designCode: body.designCode.trim(),
    description: (body.description || "").trim(),
    active: body.active === undefined ? true : body.active,
    createdAt: now,
    updatedAt: now
};
msg.createdDesign = design;
msg.payload = [
    {tileSize: design.tileSize, designCode: design.designCode},
    {$setOnInsert: design},
    {upsert: true}
];
return [msg, null];

const result = msg.payload;
msg.headers = {"Content-Type": "application/json"};
if (!result || result.acknowledged !== true) {
    msg.statusCode = 500;
    msg.payload = {success: false, error: "Database did not acknowledge the write."};
} else if (result.upsertedCount === 1) {
    msg.statusCode = 201;
    msg.payload = {success: true, designCode: {...msg.createdDesign, _id: result.upsertedId}};
} else {
    msg.statusCode = 409;
    msg.payload = {success: false, error: "This design code already exists for the selected tile size."};
}
delete msg.createdDesign;
return msg;

const duplicate = /E11000|duplicate key/i.test(String(msg.error?.message || ""));
msg.statusCode = duplicate ? 409 : 500;
msg.headers = {"Content-Type": "application/json"};
msg.payload = {
    success: false,
    error: duplicate ? "This design code already exists for the selected tile size." : "Unable to save design code. Check the Node-RED server logs."
};
delete msg.createdDesign;
return msg;
